#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    // XOR over booleans can be represented as parity of true values.
    int parity = 0;  // 0 -> false, 1 -> true

    #pragma omp parallel for reduction(^:parity)
    for (std::size_t i = 0; i < x.size(); ++i) {
        parity ^= static_cast<int>(x[i]);
    }

    return parity != 0;
}
